<template>
  <div>
    <el-aside class="aside-left">
      <el-menu
        :default-active="activeMenu.path"
        class="el-menu-vertical-left"
        background-color="#545c64"
        text-color="#fff"
        active-text-color="#ffd04b"
        router
      >
        <!-- 递归渲染菜单 -->
        <template v-for="(item, index) in menuList">
          <!-- 有子菜单的情况 -->
          <el-submenu v-if="item.children && item.children.length > 0" :index="item.path" :key="index">
            <template slot="title">
              <i :class="item.icon || 'el-icon-menu'"></i>
              <span>{{ item.label }}</span>
            </template>
            <!-- 递归渲染子菜单 -->
            <template v-for="(child, childIndex) in item.children">
              <el-menu-item v-if="!child.children || child.children.length === 0" :index="child.path" :key="childIndex" @click="handleMenuClick(child, [item])">
                <i :class="child.icon || 'el-icon-document'"></i>
                <span>{{ child.label }}</span>
              </el-menu-item>

              <!-- 处理多级子菜单 -->
              <el-submenu v-else :index="child.path" :key="childIndex">
                <template slot="title">
                  <i :class="child.icon || 'el-icon-folder'"></i>
                  <span>{{ child.label }}</span>
                </template>
                <!-- 第三级菜单 -->
                <el-menu-item v-for="(grandChild, gcIndex) in child.children" :key="gcIndex" :index="grandChild.path" @click="handleMenuClick(grandChild, [item, child])">
                  {{ grandChild.label }}
                </el-menu-item>
              </el-submenu>
            </template>
          </el-submenu>

          <!-- 没有子菜单的情况 -->
          <el-menu-item v-else :index="item.path" :key="index" @click="handleMenuClick(item, [])">
            <i :class="item.icon || 'el-icon-document'"></i>
            <span>{{ item.label }}</span>
          </el-menu-item>
        </template>
      </el-menu>
    </el-aside>
  </div>
</template>

<script>
export default {
  name: 'AsideLeft',
  data() {
    return {
      menuList: [
        {
          path: "", //路由路径
          icon: "", //图标
          label: "基础管理", //菜单名
          children: [
            { icon: "", path: "", label: "人员管理" },
            { icon: "", path: "", label: "物资管理" },
            { icon: "", path: "", label: "器材管理" },
            { icon: "", path: "/deviceData", label: "设备管理" },
          ],
        },
        {
          path: "", //路由路径
          icon: "", //图标
          label: "标准管理", //菜单名
          children: [
            { icon: "", path: "", label: "人员标准" },
            { icon: "", path: "", label: "物资标准" },
            { icon: "", path: "", label: "器材标准" },
            { icon: "", path: "/deviceStandard", label: "设备标准" },
          ],
        },
        {
          path: "", //路由路径
          icon: "", //图标
          label: "类型管理", //菜单名
          children: [
            { icon: "", path: "", label: "人员类型" },
            { icon: "", path: "/suppliesType", label: "物资类型" },
            { icon: "", path: "/qwe", label: "器材类型" },
            { icon: "", path: "/deviceType", label: "设备类型" },
          ],
        },
        {
          path: "", //路由路径
          icon: "", //图标
          label: "重量管理", //菜单名
          children: [
            { icon: "", path: "", label: "物资重量" },
            { icon: "", path: "", label: "器材重量" },
          ],
        },
        {
          path: "", //路由路径
          icon: "", //图标
          label: "系统管理", //菜单名
          children: [
            { icon: "", path: "/authorityManage", label: "权限管理" },
            { icon: "", path: "", label: "日志管理" },
          ],
        },
      ],                            // 左侧菜单项
      activeMenu: {
        path: ''
      },                            // 当前菜单
      menuFullPathName: '',         // 当前选中菜单名
    }
  },

  // watch: {
  //   $route: {
  //     handler: function(route) {
  //       if (route.path) {
  //         // this.$set(this.activeMenu, 'path', route.path)
  //         this.$bus.$emit('getBreadText', this.menuFullPathName)
  //       }
  //     }
  //   }
  // },

  created() {
    // 激活菜单样式
    this.$set(this.activeMenu, 'path', this.$route.path)
    // 生成面包屑文本
    const routeName  = this.$route.path
    for (let index = 0; index < this.menuList.length; index++) {
      const parentMenuName = this.menuList[index].label
      if (this.menuList[index].children?.length > 0) {
        const child = this.menuList[index].children
        for (let i = 0; i < child.length; i++) {
          if (child[i].path == routeName) {
            this.menuFullPathName = (parentMenuName + ' / ' + child[i].label)
            this.$nextTick(() => {
              // 发送至面包屑组件
              this.$bus.$emit('getBreadText', this.menuFullPathName)
            })
          }
        }
      }  
    }
  },

  methods: {
    handleMenuClick(currentItem, parentItems) {
      const parentMenuName = parentItems.map(item => item.label)
      // 当前项名称
      const childMenuName = currentItem.label
      // 组合成完整路径（例如：系统设置 / 角色管理 / 角色列表）
      this.menuFullPathName = [...parentMenuName, childMenuName].join(' / ')
      // 发送至面包屑组件
      this.$bus.$emit('getBreadText', this.menuFullPathName)
    },
  }

}

</script>

<style lang="scss" scoped>
.aside-left {
  background-color: #fff;
  border-right: 1px solid #e6e6e6;
  padding: 0 0;
  height: 100%;
}
.el-menu-vertical-left{
  width: 100%;
  min-height: 400px;
  height: 100%;
}
</style>