<template>
  <div>
    <el-header class="breadcrumb-header">
      <el-breadcrumb separator="/">
        <el-breadcrumb-item>{{ menuFullPathName }}</el-breadcrumb-item>
      </el-breadcrumb>
    </el-header>
  </div>
</template>

<script>
export default {
  name: 'BreadCrumb',
  data() {
    return {
      menuFullPathName: ''      // 面包屑文本
    }
  },

  // watch: {
  //   $route: {
  //     handler(route) {
  //       console.log(route.matched)
  //     }
  //   }
  // },

  mounted() {
    // 监听菜单发来的文本
    this.$bus.$on('getBreadText', this.createBreadText)
  },

  methods: {
    // 面包屑文本赋值
    createBreadText(val) {
      this.menuFullPathName = val
    }
  }

}

</script>

<style lang="scss" scoped>
.breadcrumb-header {
  padding: 10px 20px;
  border-bottom: 1px solid #e6e6e6;
  height: auto;
}
</style>